use ingetrazo_core::{visible_ray_index::VisibleRayIndex,math::Ray};use glam::DVec3;
fn main(){let dir=std::path::PathBuf::from(std::env::args_os().nth(1).unwrap());let source:serde_json::Value=serde_json::from_slice(&std::fs::read(dir.join("original.json")).unwrap()).unwrap();let mut rows=vec![];for row in source["cases"].as_array().unwrap(){let name=row["name"].as_str().unwrap();let scene=ingetrazo_formats::load_igz(&dir.join(format!("{name}.igz"))).unwrap();let index=VisibleRayIndex::new(&scene,1024*1024).unwrap();let ray=Ray::new(DVec3::from_array(serde_json::from_value(row["origin"].clone()).unwrap()),DVec3::from_array(serde_json::from_value(row["direction"].clone()).unwrap()));rows.push(serde_json::json!({"name":name,"distance":index.distance(&scene,&ray),"triangles":index.triangle_count(),"fallback_distance":VisibleRayIndex::direct_hit(&scene,&ray).map(|h|h.2),"tiny_admission_refused":VisibleRayIndex::new(&scene,1).is_err()}));}println!("{}",serde_json::json!({"cases":rows}));}
